<?php
declare(strict_types=1);

/*
    filename: install_admin_backup_manager_v001_20260903_125923pm.php
    VERSION: v001
    LAST MODIFIED: 9/3/2026 12:59:23 pm

    PURPOSE:
    - Install unified admin_backup.php manager.
    - Convert existing admin_db_backup.php into guarded admin_backup_db_helper.php.
    - Add guarded admin_backup_files_helper.php.
    - Remove original admin_db_backup.php only after successful install.
    - Provide preflight, apply and rollback.
*/

if (session_status() === PHP_SESSION_NONE) session_start();
require_once $_SERVER['DOCUMENT_ROOT'] . '/config.php';
require_once $_SERVER['DOCUMENT_ROOT'] . '/config_mrl.php';
require_once $_SERVER['DOCUMENT_ROOT'] . '/class.user.php';
$user_home = new USER();
if (!$user_home->is_logged_in()) { $user_home->redirect('login.php'); exit; }
if (!isAdmin($_SESSION['userSession'] ?? null)) { http_response_code(403); exit('Not authorized.'); }

$root=__DIR__;
$source=$root.'/admin_db_backup.php';
$targetManager=$root.'/admin_backup.php';
$targetDb=$root.'/admin_backup_db_helper.php';
$targetFiles=$root.'/admin_backup_files_helper.php';
$backupBase=$root.'/_migration_backups/admin_backup_manager_v001_20260903_125923pm';
$domainRoot=dirname($root);
$filesBackupDir=$domainRoot.'/_mrl_backups/files';
$action=(string)($_POST['action']??'');
$msg=[];$err=[];
function iab_h($v): string { return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); }
function iab_write(string $path,string $b64): bool { $data=base64_decode($b64,true); return $data!==false && file_put_contents($path,$data,LOCK_EX)!==false; }
$payloads=[
    'admin_backup.php' => '',
    'admin_backup_db_helper.php' => '',
    'admin_backup_files_helper.php' => ''
];

$pre=[
 ['Current admin_db_backup.php exists',is_file($source)],
 ['public_html writable',is_writable($root)],
 ['ZipArchive available',class_exists('ZipArchive')],
 ['ZipArchive setMtimeName available',class_exists('ZipArchive') && method_exists('ZipArchive','setMtimeName')],
 ['Domain root writable',is_writable($domainRoot)],
];
$preOk=true; foreach($pre as $p) if(!$p[1]) $preOk=false;

if($action==='apply' && $preOk){{
    if(!is_dir($backupBase) && !@mkdir($backupBase,0755,true)) $err[]='Could not create installer backup folder.';
    if(!$err){{
        foreach([$source,$targetManager,$targetDb,$targetFiles] as $p){{ if(is_file($p) && !@copy($p,$backupBase.'/'.basename($p))) $err[]='Could not back up '.basename($p); }}
    }}
    if(!$err && !is_dir($filesBackupDir) && !@mkdir($filesBackupDir,0755,true)) $err[]='Could not create outside-public_html files backup folder.';
    if(!$err){{
        foreach($payloads as $name=>$b64){{ if(!iab_write($root.'/'.$name,$b64)) $err[]='Could not write '.$name; }}
    }}
    if(!$err){{
        foreach([$targetManager,$targetDb,$targetFiles] as $p){{ $out=[];$rc=0; @exec('php -l '.escapeshellarg($p).' 2>&1',$out,$rc); if($rc!==0) $err[]='PHP syntax failed for '.basename($p).': '.implode(' ',$out); }}
    }}
    if(!$err){{
        if(!@unlink($source)) $err[]='New files installed, but could not remove original admin_db_backup.php.';
        else $msg[]='INSTALL COMPLETE — admin_backup.php is now the Backup Manager front door.';
    }}
}}

if($action==='rollback'){{
    $old=$backupBase.'/admin_db_backup.php';
    if(!is_file($old)) $err[]='Rollback source admin_db_backup.php not found.';
    else{{
        foreach([$targetManager,$targetDb,$targetFiles] as $p) if(is_file($p)) @unlink($p);
        if(@copy($old,$source)) $msg[]='ROLLBACK COMPLETE — original admin_db_backup.php restored.'; else $err[]='Could not restore original admin_db_backup.php.';
    }}
}}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Install MRL Backup Manager v001</title>
<style>body{{margin:0;background:#111;color:#eee;font-family:Arial}}.wrap{{max-width:1000px;margin:24px auto;padding:0 14px}}.card{{background:#1b1b1b;border:1px solid #333;border-radius:10px;padding:18px;margin-bottom:16px}}h1{{color:#d8c08a}}table{{width:100%;border-collapse:collapse}}td,th{{padding:9px;border-bottom:1px solid #3a3a3a;text-align:left}}.pass{{color:#58d68d;font-weight:bold}}.fail{{color:#ff6b6b;font-weight:bold}}.btn{{border:0;border-radius:8px;padding:12px 18px;font-weight:bold;font-size:16px;cursor:pointer}}.safe{{background:#237a45;color:#fff}}.danger{{background:#b82b2b;color:#fff}}.disabled{{background:#555;color:#bbb}}.ok{{background:#123d26;border:1px solid #237a45;padding:12px;border-radius:8px}}.err{{background:#531f1f;border:1px solid #b82b2b;padding:12px;border-radius:8px}}code{{color:#ffd18a}}</style></head><body><div class="wrap">
<div class="card"><h1>Install MRL Backup Manager v001</h1><p>Creates <code>admin_backup.php</code>, DB helper, and Files helper. Existing DB backups stay in <code>/public_html/db_backups/</code>. New file ZIPs go outside public_html at <code><?php echo iab_h($filesBackupDir); ?></code>.</p></div>
<?php if($msg):?><div class="card ok"><?php echo iab_h(implode(' | ',$msg));?></div><?php endif;?><?php if($err):?><div class="card err"><?php echo iab_h(implode(' | ',$err));?></div><?php endif;?>
<div class="card"><h2>Preflight</h2><table><tr><th>Check</th><th>Status</th></tr><?php foreach($pre as $p):?><tr><td><?php echo iab_h($p[0]);?></td><td class="<?php echo $p[1]?'pass':'fail';?>"><?php echo $p[1]?'PASS':'FAIL';?></td></tr><?php endforeach;?></table></div>
<div class="card"><h2>Apply</h2><p>Installer backs up any files it changes first. The original <code>admin_db_backup.php</code> is removed only after the new files are written and syntax-checked.</p><form method="post"><input type="hidden" name="action" value="apply"><button class="btn <?php echo $preOk?'safe':'disabled';?>" <?php echo $preOk?'':'disabled';?>>Apply Backup Manager v001</button></form></div>
<div class="card"><h2>Rollback</h2><p>Restores the original <code>admin_db_backup.php</code> from the installer backup and removes the three new manager/helper files.</p><form method="post" onsubmit="return confirm('Rollback Backup Manager v001?');"><input type="hidden" name="action" value="rollback"><button class="btn danger">Rollback</button></form></div>
</div></body></html>
